import puppeteer from 'puppeteer-core';
import assert from 'node:assert/strict';
const base=process.env.TEST_URL,exe=process.env.CHROME_PATH;if(!base||!exe)throw Error('TEST_URL/CHROME_PATH missing');
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const browser=await puppeteer.launch({executablePath:exe,headless:true,args:['--no-sandbox','--disable-gpu','--disable-dev-shm-usage'],timeout:30000});
const ctx=await browser.createBrowserContext(),p=await ctx.newPage(),errors=[];
await p.setViewport({width:390,height:844});
p.on('pageerror',e=>errors.push(String(e.stack||e)));p.on('console',m=>{if(m.type()==='error'&&!/Failed to load resource.*404/i.test(m.text())&&!/PeerJS/i.test(m.text()))errors.push(m.text())});
await p.evaluateOnNewDocument(()=>{localStorage.setItem('BombermanPlayerName','PhoneTest467');if(navigator.serviceWorker)navigator.serviceWorker.register=()=>Promise.resolve({})});
try{
 await p.goto(base,{waitUntil:'domcontentloaded',timeout:20000});
 await p.waitForFunction(()=>window.BomberRelease150?.version==='v0.15.5'&&window.BomberObserver154?.version==='v0.15.4.1'&&window.BomberObserver153?.handledObserveSerial&&window.BomberBehavior157?.version==='v0.15.7'&&window.gGameEngine?.menu,{timeout:30000});
 assert.equal(await p.evaluate(()=>BomberObserver154.state().mobile),true,'390px page did not enter mobile chat mode');
 await p.evaluate(()=>BomberOnline.openLobby());await p.waitForFunction(()=>document.getElementById('v152ObserveBtn'),{timeout:5000});
 await p.evaluate(()=>{const old=Math.random;Math.random=()=>.99;document.getElementById('v152ObserveBtn').click();Math.random=old});
 await p.waitForFunction(()=>BomberHumanObserver152.state().mode==='observe'&&gGameEngine.bots?.length===4&&B115.role==='roster'&&BomberObserver153.audit(),{timeout:10000});
 const first=await p.evaluate(()=>({names:BomberHumanObserver152.state().profiles.map(x=>x.name),audit:BomberObserver153.audit(),serial:BomberHumanObserver152.state().roundSerial}));
 assert.ok(first.audit.state>=1&&first.audit.state<=10,'first observe entry was not staged');
 // Let the v0.15.7 local "spectating" notice land, then isolate the two-message preview assertion.
 await sleep(360);await p.evaluate(()=>{BomberBehavior157.clearChat();B115.appendChat('NeonFox','phone recent one',false);B115.appendChat('PixelPilot','phone recent two',false)});await sleep(140);
 const compact=await p.evaluate(()=>{const w=document.getElementById('v154MobileChat'),pr=document.getElementById('v154MobileChatPreview'),game=document.getElementById('game'),wr=w?.getBoundingClientRect(),gr=game?.getBoundingClientRect(),panel=document.getElementById('chatPanel');return{visible:!!(w&&!w.hidden&&getComputedStyle(w).display!=='none'),lines:pr?.querySelectorAll('.v154_mobile_chat_line').length||0,text:pr?.textContent||'',below:!!(wr&&gr&&wr.top>=gr.bottom-1),afterGame:!!(w&&w.previousElementSibling===game),desktopHidden:!panel||panel.hidden||getComputedStyle(panel).display==='none'}});
 assert.equal(compact.visible,true,'phone compact chat is not visible');assert.equal(compact.lines,2,'phone compact chat is not limited to two latest messages');assert.ok(compact.text.includes('phone recent one')&&compact.text.includes('phone recent two'),'phone preview is missing latest messages');assert.equal(compact.below,true,'phone chat strip is not below gameplay box');assert.equal(compact.afterGame,true,'phone chat strip is not placed immediately after game box');assert.equal(compact.desktopHidden,true,'desktop chat panel remained visible on phone');
 await p.click('#v154MobileChatBtn');await sleep(80);
 const readOnly=await p.evaluate(()=>({open:document.getElementById('v154MobileChatOverlay')?.hidden===false,formHidden:document.getElementById('v154MobileChatForm')?.hidden===true,readOnly:document.getElementById('v154MobileChatReadOnly')?.hidden===false,full:document.getElementById('v154MobileChatFullMessages')?.textContent||''}));
 assert.equal(readOnly.open,true,'phone full chat sheet did not open');assert.equal(readOnly.formHidden,true,'observer was allowed to type before joining');assert.equal(readOnly.readOnly,true,'observer read-only note missing');assert.ok(readOnly.full.includes('phone recent one')&&readOnly.full.includes('phone recent two'),'full chat sheet does not mirror chat history');
 await p.evaluate(()=>B115.appendChat('LongMessage','this deliberately long phone chat message should wrap onto multiple readable lines instead of being squeezed into a clipped desktop-height pill',false));await sleep(140);
 const readable=await p.evaluate(()=>{const rows=[...document.querySelectorAll('#v154MobileChatFullMessages .v154_mobile_chat_full_line')],r=rows.at(-1),span=r?.querySelector('span'),cs=r&&getComputedStyle(r),ss=span&&getComputedStyle(span);return{count:rows.length,height:r?.getBoundingClientRect().height||0,clientHeight:r?.clientHeight||0,scrollHeight:r?.scrollHeight||0,overflow:cs?.overflow||'',whiteSpace:cs?.whiteSpace||'',spanHeight:span?.getBoundingClientRect().height||0,spanOverflow:ss?.overflow||'',hasDesktopClass:!!r?.classList.contains('chat_line'),text:r?.textContent||''}});
 assert.ok(readable.count>=3,'full mobile chat did not render rebuilt message rows');assert.equal(readable.hasDesktopClass,false,'mobile full chat still clones the desktop chat_line class');assert.ok(readable.text.includes('deliberately long phone chat message'),'long mobile message missing');assert.ok(readable.height>=40,'long mobile chat row is still vertically squeezed');assert.ok(readable.scrollHeight<=readable.clientHeight+1,'mobile chat text is still vertically clipped');assert.equal(readable.overflow,'visible','mobile full chat row still hides overflow');assert.equal(readable.whiteSpace,'normal','mobile full chat row does not wrap normally');assert.ok(readable.spanHeight>=30,'mobile chat body did not expand to multiple lines');assert.equal(readable.spanOverflow,'visible','mobile chat body still hides overflow');
 await p.click('#v154MobileChatClose');
 await p.evaluate(()=>BomberHumanObserver152.debug.finishObservedRound());
 await p.waitForFunction(()=>BomberObserver154.state().freshResets>=1&&BomberHumanObserver152.state().mode==='observe',{timeout:7000});await sleep(120);
 const fresh=await p.evaluate(()=>({names:BomberHumanObserver152.state().profiles.map(x=>x.name),wood:gGameEngine.tiles.filter(t=>t.material==='wood').length,serial:BomberHumanObserver152.state().roundSerial,handled:BomberObserver153.handledObserveSerial(),status:document.getElementById('v152ObserverStatus')?.textContent||''}));
 assert.deepEqual(fresh.names,first.names,'watched-through rematch changed the two players');assert.ok(fresh.serial>first.serial,'watched-through rematch did not advance the round');assert.equal(fresh.handled,fresh.serial,'progression owner did not finish the new serial before clean reset');assert.ok(fresh.wood>=first.audit.initialWood-1,'watched-through rematch did not restore a fresh board');assert.ok(!/believable match/i.test(fresh.status),'fresh-round observer status restored old believable-match wording');
 await p.click('#v152JoinNextBtn');await sleep(100);
 const queued=await p.evaluate(()=>{const h=document.getElementById('v152ObserverHud');return{queued:BomberHumanObserver152.state().joinQueued,hidden:!h||h.hidden||getComputedStyle(h).display==='none',classed:document.body.classList.contains('v154_observer_queued')}});
 assert.equal(queued.queued,true,'Join next round did not queue');assert.equal(queued.hidden,true,'Observing Random Match card stayed visible after queueing');assert.equal(queued.classed,true,'queued observer UI state missing');
 await p.evaluate(()=>BomberHumanObserver152.debug.finishObservedRound());await p.waitForFunction(()=>BomberHumanObserver152.state().mode==='joined'&&gGameEngine.players?.length===1&&gGameEngine.bots?.length===3&&B115.role==='roster',{timeout:7000});
 await p.click('#v154MobileChatBtn');await p.waitForFunction(()=>document.getElementById('v154MobileChatOverlay')?.hidden===false&&document.getElementById('v154MobileChatForm')?.hidden===false,{timeout:2000});
 await p.type('#v154MobileChatInput','hello from mobile');await p.click('#v154MobileChatForm button[type="submit"]');await sleep(140);
 const sent=await p.evaluate(()=>({history:document.getElementById('chatMessages')?.textContent||'',full:document.getElementById('v154MobileChatFullMessages')?.textContent||'',value:document.getElementById('v154MobileChatInput')?.value||'',readOnly:document.getElementById('v154MobileChatReadOnly')?.hidden===false}));
 assert.ok(sent.history.includes('hello from mobile'),'joined mobile chat did not append/send message');assert.ok(sent.full.includes('hello from mobile'),'full mobile sheet did not refresh after send');assert.equal(sent.value,'','mobile message input did not clear');assert.equal(sent.readOnly,false,'joined mobile chat remained read-only');
 await p.click('#v154MobileChatClose');
 if(errors.length)throw Error('browser errors: '+errors.join(' | '));
 console.log('V1541_MOBILE_CHAT_SMOKE PASS',JSON.stringify({compact,readOnly,readable,fresh,queued,sent}));
} finally {await ctx.close().catch(()=>{});await browser.close().catch(()=>{})}
